// Production key holder: an HMAC key generated by AWS KMS that never leaves it.
// See DESIGN.md, section 13.
//
// KMS computes HMAC-SHA-256 over the same message the in-memory deriver uses, so both give the
// same pepper for the same key bytes. This service only ever sees MAC results.
import { encodeInput, keyCheckFromMac, keyCheckMessage, macToPepper, type PepperDeriver } from './derive';

/** The one operation the service needs from a key holder: HMAC-SHA-256 under the pepper key. */
export interface MacClient {
  generateMac(message: Uint8Array): Promise<Uint8Array>;
}

/** What the service checks about the KMS key before it serves. */
export type KmsKeyInfo = {
  arn: string;
  keySpec?: string;
  keyUsage?: string;
  origin?: string;
  enabled?: boolean;
  multiRegion?: boolean;
  pendingDeletion: boolean;
};

/** A deriver over any MAC client. */
export function macDeriver(client: MacClient, version: number): PepperDeriver {
  return {
    version,
    async derive(iss, sub) {
      if (!iss || !sub) throw new Error('EMPTY_INPUT');
      return macToPepper(await client.generateMac(encodeInput(iss, sub)));
    },
  };
}

/** The key check value of the key behind a MAC client. One MAC call; reveals nothing about peppers. */
export async function macKeyCheckValue(client: MacClient): Promise<string> {
  return keyCheckFromMac(await client.generateMac(keyCheckMessage()));
}

/**
 * Refuses a KMS key that is not what the design calls for. A key of the wrong kind would fail
 * later anyway; a key scheduled for deletion would work today and end recovery for every user
 * in a few weeks.
 */
export function assertPepperKey(info: KmsKeyInfo): void {
  if (info.keySpec !== 'HMAC_256') throw new Error('KMS key: key spec must be HMAC_256');
  if (info.keyUsage !== 'GENERATE_VERIFY_MAC') throw new Error('KMS key: key usage must be GENERATE_VERIFY_MAC');
  if (info.origin !== 'AWS_KMS') throw new Error('KMS key: key material must be generated by AWS KMS');
  if (info.pendingDeletion) throw new Error('KMS key: the key is scheduled for deletion');
  if (!info.enabled) throw new Error('KMS key: the key is disabled');
}

/**
 * The AWS KMS client. `keyId` should be the key's ARN, so a request can never land on a key of
 * the same alias in another account or Region. Credentials come from the AWS SDK's default
 * chain (the service's role).
 */
export async function awsKms(keyId: string, region: string): Promise<{ client: MacClient; describe(): Promise<KmsKeyInfo> }> {
  const { KMSClient, GenerateMacCommand, DescribeKeyCommand } = await import('@aws-sdk/client-kms');
  const kms = new KMSClient({ region });
  return {
    client: {
      async generateMac(message) {
        const out = await kms.send(new GenerateMacCommand({ KeyId: keyId, Message: message, MacAlgorithm: 'HMAC_SHA_256' }));
        if (!out.Mac || out.Mac.length !== 32) throw new Error('KMS returned no 32-byte MAC');
        return out.Mac;
      },
    },
    async describe() {
      const { KeyMetadata: m } = await kms.send(new DescribeKeyCommand({ KeyId: keyId }));
      if (!m) throw new Error('KMS returned no key metadata');
      return {
        arn: m.Arn ?? keyId,
        keySpec: m.KeySpec,
        keyUsage: m.KeyUsage,
        origin: m.Origin,
        enabled: m.Enabled,
        multiRegion: m.MultiRegion,
        pendingDeletion: m.KeyState === 'PendingDeletion' || m.KeyState === 'PendingReplicaDeletion',
      };
    },
  };
}
